# nginx — permanently redirect HTTP to HTTPS + HSTS
server {
    listen 80;
    server_name shop.example.com;
    return 301 https://$host$request_uri;
}
server {
    listen 443 ssl http2;
    server_name shop.example.com;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
    # ssl_certificate /etc/letsencrypt/live/shop.example.com/fullchain.pem;   # certbot --nginx -d shop.example.com
}

// AI bots do not execute JavaScript; https://shop.example.com/urun/filtre-klasik must return its content in the first HTML.
// Next.js (App Router) — render the page as a Server Component:
// app/product/[slug]/page.tsx
export const revalidate = 3600; // ISR: static regeneration once an hour

export default async function ProductPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const product = await getProduct(slug); // fetch data on the server (NOT useEffect + fetch)
  return (
    <article>
      <h1>{product.name}</h1>
      <p>{product.summary}</p>
      <ProductSpecsTable specs={product.specs} />
    </article>
  );
}

